#include <iostream>
using namespace std;

int main() {
    cout << 2 + 3 * 4 << endl;      // the multiply goes first
    cout << (2 + 3) * 4 << endl;    // brackets go first
    cout << 20 - 6 / 2 << endl;     // the divide goes first
    cout << 10 - 4 - 3 << endl;     // equal rank: left to right
    return 0;
}

